fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    // Inputs must be non-empty and either the same length or one of them has length 1
    debug_assert!(m > 0 && n > 0 && (m == n || m == 1 || n == 1));

    let len = m.max(n);

    // If `a` has length equal to the result length, just reuse it;
    // otherwise it must be length 1, so repeat its single value.
    let out_a = if m == len {
        a
    } else {
        vec![a[0]; len]
    };

    // Same logic for `b`.
    let out_b = if n == len {
        b
    } else {
        vec![b[0]; len]
    };

    (out_a, out_b)
}